<!doctype html><html lang="hu"><head><meta charset="utf-8"><style>@page{margin:32px}body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#1f2937}h1{font-size:20px}h2{font-size:13px;margin:18px 0 7px}table{width:100%;border-collapse:collapse}td{padding:6px;border-bottom:1px solid #d1d5db;vertical-align:top}.key{width:35%;font-weight:bold;background:#f3f4f6}</style></head><body>
<h1>Ügyfél igény összesítő</h1><p>Beküldve: {{ $quoteRequest->created_at->format('Y.m.d. H:i') }}</p>
<h2>Kapcsolattartó</h2><table><tr><td class="key">Cégnév</td><td>{{ $quoteRequest->company ?: '-' }}</td></tr><tr><td class="key">Név</td><td>{{ $quoteRequest->name }}</td></tr><tr><td class="key">Email</td><td>{{ $quoteRequest->email }}</td></tr><tr><td class="key">Telefonszám</td><td>{{ $quoteRequest->phone }}</td></tr></table>
<h2>Megadott igény</h2><table><tr><td class="key">Épület típusa</td><td>{{ \App\Filament\Resources\QuoteRequests\Schemas\QuoteRequestForm::BUILDING_TYPES[$quoteRequest->building_type] ?? $quoteRequest->building_type }}</td></tr><tr><td class="key">Kért rendszerek</td><td>{{ collect($quoteRequest->requested_systems ?? [])->map(fn ($item) => \App\Filament\Resources\QuoteRequests\Schemas\QuoteRequestForm::REQUESTED_SYSTEMS[$item] ?? $item)->join(', ') ?: '-' }}</td></tr><tr><td class="key">Megjegyzés</td><td>{!! nl2br(e($quoteRequest->message ?: '-')) !!}</td></tr><tr><td class="key">Tervezett keret</td><td>{{ $quoteRequest->budget_huf ? number_format((float) $quoteRequest->budget_huf, 0, ',', ' ').' Ft' : '-' }}</td></tr><tr><td class="key">Kivitelezést kér</td><td>{{ $quoteRequest->wants_installation ? 'igen' : 'nem' }}</td></tr></table>
</body></html>
